" />\n                <label class=\"form-check-label\" for=\"requiredCheck\">\n                    Wymagany (Użytkownik nie może odznaczyć tego zakresu podczas zgody)\n                </label>\n            </div>\n\n            <div class=\"form-check mb-4\">\n                <input asp-for=\"Input.Emphasize\" class=\"form-check-input\" type=\"checkbox\" id=\"emphasizeCheck\" />\n                <label class=\"form-check-label\" for=\"emphasizeCheck\">\n                    Wyróżniony (Podświetlony na ekranie zgody jako uprawnienie wrażliwe)\n                </label>\n            </div>\n\n            <div class=\"d-flex gap-2\">\n                <button type=\"submit\" class=\"btn btn-primary px-4\">\n                    <i class=\"bi bi-check-lg me-1\"></i> Zapisz Zakres API\n                </button>\n                <a asp-page=\"Index\" class=\"btn btn-outline-secondary\">Anuluj</a>\n            </div>\n        </form>\n    </div>\n</div>\n"
