    "content": "@page\n@model Quorum.Backend.Areas.Admin.Pages.Clients.CreateModel\n@{\n    ViewData[\"Title\"] = \"Nowy Klient OIDC\";\n}\n\n<div class=\"mb-4\">\n    <a asp-page=\"Index\" class=\"text-decoration-none small text-muted\">\n        <i class=\"bi bi-arrow-left me-1\"></i> Powrót do listy klientów\n    </a>\n    <h2 class=\"h4 mt-2\">Dodaj nowego klienta OAuth2 / OIDC</h2>\n</div>\n\n<div class=\"card border-0 shadow-sm col-lg-8\">\n    <div class=\"card-body p-4\">\n        <form method=\"post\">\n            <div asp-validation-summary=\"ModelOnly\" class=\"alert alert-danger\" role=\"alert\"></div>\n\n            <div class=\"mb-3\">\n                <label asp-for=\"Input.ClientId\" class=\"form-label fw-semibold\">Client ID <span class=\"text-danger\">*</span></label>\n                <input asp-for=\"Input.ClientId\" class=\"form-control font-monospace\" placeholder=\"np. my-spa-app lub billing-api\" />\n                <span asp-validation-for=\"Input.ClientId\" class=\"text-danger small\"></span>\n            </div>\n\n            <div class=\"mb-3\">\n                <label asp-for=\"Input.ClientName\" class=\"form-label fw-semibold\">Nazwa wyświetlana <span class=\"text-danger\">*</span></label>\n                <input asp-for=\"Input.ClientName\" class=\"form-control\" placeholder=\"np. Panel Klienta Web\" />\n                <span asp-validation-for=\"Input.ClientName\" class=\"text-danger small\"></span>\n            </div>\n\n            <div class=\"mb-3\">\n                <label asp-for=\"Input.GrantType\" class=\"form-label fw-semibold\">Typ Przepływu (Grant Type)</label>\n                <select asp-for=\"Input.GrantType\" class=\"form-select\">\n                    <option value=\"client_credentials\">Client Credentials (Aplikacje w tle / M2M)</option>\n                    <option value=\"authorization_code\">Authorization Code + PKCE (SPA / Web MVC / Mobile)</option>\n                </select>\n            </div>\n\n            <div class=\"mb-3\">\n                <label asp-for=\"Input.ClientSecret\" class=\"form-label fw-semibold\">Client Secret (Hasło klienta)</label>\n                <input asp-for=\"Input.ClientSecret\" class=\"form-control\" type=\"password\" placeholder=\"Wprowadź tajny klucz (zostanie zhaszowany SHA-256)\" />\n                <div class=\"form-text small\">Wymagane dla Client Credentials. Opcjonalne dla publicznych klientów z PKCE.</div>\n            </div>\n\n            <div class=\"mb-3\">\n                <label asp-for=\"Input.AllowedScopes\" class=\"form-label fw-semibold\">Dozwolone Zakresy (Scopes)</label>\n                <input asp-for=\"Input.AllowedScopes\" class=\"form-control font-monospace\" placeholder=\"openid profile email api1\" />\n                <div class=\"form-text small\">Oddziel spacjami, np. <code>openid profile email api1 api.write</code></div>\n            </div>\n\n            <div class=\"mb-3\">\n                <label asp-for=\"Input.RedirectUris\" class=\"form-label fw-semibold\">Redirect URIs (Dla Authorization Code)</label>\n                <input asp-for=\"Input.RedirectUris\" class=\"form-control\" placeholder=\"https://localhost:5002/signin-oidc, https://myapp.com/callback\" />\n                <div class=\"form-text small\">Oddziel przecinkami, jeśli podajesz kilka adresów URL.</div>\n            </div>\n\n            <div class=\"form-check mb-4\">\n                <input asp-for=\"Input.RequirePkce\" class=\"form-check-input\" type=\"checkbox\" id=\"requirePkceCheck\" />\n                <label class=\"form-check-label\" for=\"requirePkceCheck\">\n                    Wymagaj Proof Key for Code Exchange (PKCE) - zalecane dla bezpieczeństwa\n                </label>\n            </div>\n\n            <div class=\"d-flex gap-2\">\n                <button type=\"submit\" class=\"btn btn-primary px-4\">\n                    <i class=\"bi bi-check-lg me-1\"></i> Zapisz Klienta w Bazie\n                </button>\n                <a asp-page=\"Index\" class=\"btn btn-outline-secondary\">Anuluj</a>\n            </div>\n        </form>\n    </div>\n</div>\n"
