    "path": "Quorum.Backend/Models/ApplicationUser.cs",
    "name": "Quorum.Backend/Models/ApplicationUser.cs",
    "category": "csharp",
    "description": "Rozszerzony model użytkownika IdentityUser",
    "content": "using Microsoft.AspNetCore.Identity;\n\nnamespace Quorum.Backend.Models;\n\npublic class ApplicationUser : IdentityUser\n{\n    public string? FullName { get; set; }\n    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;\n}\n"
